import apiClient from '@/lib/api/client';

async function getProducts() {
  try {
    const data = await apiClient.get('/products');
    return data;
  } catch (error) {
    console.error('Error fetching products:', error);
    throw error;
  }
}

export default async function TestPage() {
  const productsData = await getProducts();

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
      <h1>前后端通信测试</h1>
      
      <section style={{ marginBottom: '20px' }}>
        <h2>API 状态</h2>
        <p>API 地址: {process.env.NEXT_PUBLIC_MEDUSA_API_URL}</p>
        <p style={{ color: 'green' }}>✓ 后端连接正常</p>
      </section>

      <section style={{ marginBottom: '20px' }}>
        <h2>商品列表</h2>
        {productsData.products && productsData.products.length > 0 ? (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: '20px' }}>
            {productsData.products.map((product) => (
              <div key={product.id} style={{ border: '1px solid #ddd', padding: '15px', borderRadius: '8px' }}>
                <h3 style={{ margin: '0 0 10px 0' }}>{product.name}</h3>
                <p style={{ color: '#666', margin: '0' }}>{product.description.substring(0, 100)}...</p>
                <p style={{ fontWeight: 'bold', color: '#e53e3e', margin: '10px 0 0 0' }}>
                  ¥{product.price.toFixed(2)}
                </p>
              </div>
            ))}
          </div>
        ) : (
          <div style={{ padding: '20px', backgroundColor: '#f0f0f0', borderRadius: '8px' }}>
            <p>暂无商品数据</p>
            <p>请通过后端 API 添加商品数据</p>
          </div>
        )}
      </section>

      <section>
        <h2>分页信息</h2>
        {productsData.pagination && (
          <div>
            <p>当前页: {productsData.pagination.page}</p>
            <p>每页数量: {productsData.pagination.limit}</p>
            <p>总商品数: {productsData.pagination.total}</p>
            <p>总页数: {productsData.pagination.totalPages}</p>
          </div>
        )}
      </section>
    </div>
  );
}
